?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftarkan Biometrik - CryptoApp</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#17152b,#30245b);font:15px Arial;color:#292443}.panel{width:min(520px,92vw);background:#fff;padding:34px;border-radius:20px;box-shadow:0 20px 60px #0005}h1{color:#30245b;margin-top:0}.desc{line-height:1.6;color:#666}.btn{display:block;width:100%;padding:14px;border:0;border-radius:9px;background:#6c4bd2;color:#fff;font-weight:bold;cursor:pointer;margin-top:18px}.msg{margin-top:16px;padding:12px;background:#f1edff;border-radius:9px;line-height:1.5}.back{display:inline-block;margin-top:18px;color:#6042be}</style></head><body><main class="panel"><h1>🔐 Daftarkan Biometrik</h1><p class="desc">Daftarkan Windows Hello ke akun CryptoApp. Browser akan meminta verifikasi menggunakan metode yang tersedia, seperti sidik jari atau pengenalan wajah. PIN Windows Hello dapat menjadi metode cadangan jika Windows mengaturnya demikian.</p><button class="btn" id="register">Daftarkan Windows Hello</button><div class="msg" id="message">Pastikan menggunakan Chrome atau Edge dan membuka aplikasi melalui http://localhost.</div><a class="back" href="index.php">← Kembali ke CryptoApp</a></main><script>
const msg=document.getElementById('message');
const fromB64url=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(s.length/4)*4,'=')),c=>c.charCodeAt(0));
const toB64url=b=>{const a=new Uint8Array(b);let s='';a.forEach(x=>s+=String.fromCharCode(x));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
function encodeOptions(o){o.challenge=fromB64url(o.challenge);o.user.id=fromB64url(o.user.id);(o.excludeCredentials||[]).forEach(c=>c.id=fromB64url(c.id));return o;}
function encodeCredential(c){const r=c.response;return {id:c.id,rawId:toB64url(c.rawId),type:c.type,authenticatorAttachment:c.authenticatorAttachment,clientExtensionResults:c.getClientExtensionResults(),response:{clientDataJSON:toB64url(r.clientDataJSON),attestationObject:toB64url(r.attestationObject),transports:r.getTransports?r.getTransports():[]}};}
document.getElementById('register').addEventListener('click',async()=>{try{if(!window.PublicKeyCredential||!navigator.credentials){throw new Error('Browser ini belum mendukung WebAuthn. Gunakan Chrome atau Edge terbaru.');}msg.textContent='Menyiapkan permintaan Windows Hello...';const res=await fetch('biometric-options.php',{cache:'no-store'});const options=await res.json();if(!res.ok||options.ok===false)throw new Error(options.message||'Gagal mengambil opsi registrasi.');const credential=await navigator.credentials.create({publicKey:encodeOptions(options)});if(!credential)throw new Error('Registrasi dibatalkan.');msg.textContent='Memverifikasi biometrik di server...';const verify=await fetch('biometric-verify.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(encodeCredential(credential))});const result=await verify.json();if(!verify.ok||!result.ok)throw new Error(result.message||'Verifikasi gagal.');msg.textContent=result.message;}catch(e){msg.textContent='Gagal: '+e.message;}});
</script></body></html>
